static uint32_t crc32(const uint8_t *p,size_t size)
{
    uint32_t crc=0xffffffffu;
    for (size_t i=0;i<size;++i) crc=(crc>>8)^crc_table[(crc^p[i])&255u];
    return ~crc;
}
static int key_compare(const uint8_t *a,const uint8_t *b)
{
    for (unsigned at=0;at<8;at+=4) {
        uint32_t x=word(a+at),y=word(b+at);
        if (x!=y) return x<y?-1:1;
    }
    return memcmp(a+8,b+8,32);
}
static int zeros(const uint8_t *p,size_t size)
{ for (size_t i=0;i<size;++i) if (p[i]) return 0;return 1; }
void mw_scene_pack_close(MwScenePack *pack)
{
    if (!pack) return;
    if (pack->file) fclose(pack->file);
    free(pack->index);memset(pack,0,sizeof(*pack));
}
MwScenePackResult mw_scene_pack_open(MwScenePack *out,const char *path,size_t budget)
{
    if (!out || !path) return MW_SCENE_PACK_INVALID;
    memset(out,0,sizeof(*out));MwScenePack p={0};
    p.file=fopen(path,"rb");if (!p.file) return MW_SCENE_PACK_IO;
    MwScenePackResult error=MW_SCENE_PACK_INVALID;uint8_t header[128];
    if (fseek(p.file,0,SEEK_END)) { error=MW_SCENE_PACK_IO;goto failed; }
    long actual=ftell(p.file);
    if (actual<128 || (unsigned long)actual>0x7ffffffful) goto failed;
    if (fseek(p.file,0,SEEK_SET) || fread(header,1,sizeof(header),p.file)!=sizeof(header)) { error=MW_SCENE_PACK_IO;goto failed; }
    uint32_t header_crc=word(header+96);memset(header+96,0,4);
    if (memcmp(header,"MWP1",4) || word(header+4)!=1 || word(header+8)!=128 ||
        word(header+12)!=64 || !zeros(header+100,28) || crc32(header,128)!=header_crc) goto failed;
    p.count=word(header+16);p.file_bytes=word(header+28);
    if (!p.count || p.count>MW_SCENE_PACK_MAX_ENTRIES || p.file_bytes!=(uint32_t)actual) goto failed;
    size_t index_bytes=(size_t)p.count*64;
    if (index_bytes>budget) { error=MW_SCENE_PACK_CAPACITY;goto failed; }
    uint32_t payload=(uint32_t)((128+index_bytes+127)&~(size_t)127);
    if (word(header+24)!=payload || payload>p.file_bytes) goto failed;
    p.index=malloc(index_bytes);if (!p.index) { error=MW_SCENE_PACK_MEMORY;goto failed; }
    if (fread(p.index,1,index_bytes,p.file)!=index_bytes) { error=MW_SCENE_PACK_IO;goto failed; }
    if (crc32(p.index,index_bytes)!=word(header+20)) { error=MW_SCENE_PACK_CRC;goto failed; }
    uint32_t previous_end=payload;
    for (uint32_t i=0;i<p.count;++i) {
        const uint8_t *entry=p.index+(size_t)i*64;
        uint32_t kind=word(entry),offset=word(entry+40),size=word(entry+44);
        if (kind<1 || kind>3 || (kind!=3 && !zeros(entry+8,32)) || !zeros(entry+52,12) ||
            (i && key_compare(entry-64,entry)>=0) || !size ||
            offset!=((previous_end+127u)&~127u) || offset>p.file_bytes || size>p.file_bytes-offset) goto failed;
        previous_end=offset+size;
    }
    if (previous_end!=p.file_bytes) goto failed;
    memcpy(p.source_sha256,header+32,32);memcpy(p.manifest_sha256,header+64,32);*out=p;return MW_SCENE_PACK_OK;
failed:
    mw_scene_pack_close(&p);return error;
}
MwScenePackResult mw_scene_pack_find(const MwScenePack *p,uint32_t kind,uint32_t id,
    const uint8_t identity[32],MwScenePackEntry *out)
{
    if (!p || !p->file || !p->index || !out || kind<1 || kind>3 || (kind==3 && !identity)) return MW_SCENE_PACK_INVALID;
    uint8_t key[40]={0};
    for (unsigned byte=0;byte<4;++byte) { key[byte]=(uint8_t)(kind>>(byte*8));key[4+byte]=(uint8_t)(id>>(byte*8)); }
    if (kind==3) memcpy(key+8,identity,32);
    uint32_t low=0,high=p->count;
    while (low<high) {
        uint32_t mid=low+(high-low)/2;const uint8_t *entry=p->index+(size_t)mid*64;
        int compare=key_compare(key,entry);
        if (!compare) {
            *out=(MwScenePackEntry){.kind=kind,.id=id,.offset=word(entry+40),.bytes=word(entry+44),.crc32=word(entry+48)};
            memcpy(out->identity,entry+8,32);return MW_SCENE_PACK_OK;
        }
        if (compare<0) high=mid;else low=mid+1;
    }
    return MW_SCENE_PACK_NOT_FOUND;
}
MwScenePackResult mw_scene_pack_read(MwScenePack *p,uint32_t kind,uint32_t id,
    const uint8_t identity[32],void *destination,size_t capacity,size_t *bytes)
{
    if (!bytes || (!destination && capacity)) return MW_SCENE_PACK_INVALID;
    *bytes=0;MwScenePackEntry e;MwScenePackResult result=mw_scene_pack_find(p,kind,id,identity,&e);
    if (result!=MW_SCENE_PACK_OK) return result;
    if (!destination) { *bytes=e.bytes;return MW_SCENE_PACK_OK; }
    if (capacity<e.bytes) return MW_SCENE_PACK_CAPACITY;
    if (fseek(p->file,(long)e.offset,SEEK_SET) || fread(destination,1,e.bytes,p->file)!=e.bytes) return MW_SCENE_PACK_IO;
    if (crc32(destination,e.bytes)!=e.crc32) return MW_SCENE_PACK_CRC;
    *bytes=e.bytes;return MW_SCENE_PACK_OK;
}
